const fs=require("fs");
const files=["b1","b2","b3","b4","b5","b6","b7","b8","b9","b10","b11","b12","b13","b14","b15","b16","b17"];
const seen=new Set(); const out=[];
for(const f of files){
  const p="/tmp/probes/"+f+".jsonl";
  if(!fs.existsSync(p)) { console.error("missing "+p); continue; }
  for(const l of fs.readFileSync(p,"utf8").split("\n")){
    if(!l.trim()) continue;
    let s; try{ s=JSON.parse(l); }catch(e){ console.error("badline in "+f+": "+l); continue; }
